def india(sub, weight, first_m, first_f, last, cities, unis, langs, names=None):
    return dict(
        key="IN-" + sub, country="India", cc="IN", weight=weight, style="india", page="A4",
        first_m=first_m, first_f=first_f, last=last, cities=cities, loc="state",
        phone=IN_PHONE, email_domains=[("gmail.com", 70), ("yahoo.co.in", 8), ("outlook.com", 8),
                                       ("rediffmail.com", 3), ("hotmail.com", 5), ("yahoo.com", 6)],
        langs=langs, unis=unis + IN_UNIS_NATIONAL, companies=IN_COMPANIES, hospitals=IN_HOSPITALS,
        schools=IN_SCHOOLS, lawfirms=IN_LAW, currency="INR", names=names or [("gf", 1.0)],
        school_boards=True)


